-- New store functionality receives explicit action grants; ordinary roles are not auto-expanded.
SET @store_app=(SELECT id FROM iam_application WHERE app_code='SUPPLY_CHAIN');
SET @store_parent=(SELECT resource_id FROM iam_resource_ui WHERE route_key='supply.crm.customers.menu');
SELECT DISTINCT p.package_version_id,r.id,UTC_TIMESTAMP(6) FROM iam_package_resource p JOIN iam_resource r ON r.id IN (UUID_TO_BIN('883f86a1-5bf5-49df-8284-4489c44e2682'),UUID_TO_BIN('fbb1be31-d42e-44fa-a887-14d5b5aa7df2'),UUID_TO_BIN('098c9bc3-3116-442a-9d2b-80093b72c21a'),UUID_TO_BIN('f1980cc2-a38e-40d5-9849-43046c7f9b94'),UUID_TO_BIN('9221b49e-3edb-428b-95d5-a76befc576fa'),UUID_TO_BIN('d387e5fe-c69f-42d7-bac1-d4c7eacd28ad'),UUID_TO_BIN('0675bda8-9131-4082-9897-5b07df73c515'),UUID_TO_BIN('719d1406-dc05-4ebc-8507-5122d86012eb'),UUID_TO_BIN('8c91f62e-d66f-492e-a0de-ea410846bb4d'),UUID_TO_BIN('51cb06d2-7d72-4e4d-8690-5d4a60ceb084'),UUID_TO_BIN('e91aefda-fb71-461e-961b-70b190ed7eac'),UUID_TO_BIN('9fa209d0-a893-4998-831a-617bc0e41cfb')) WHERE p.resource_id=@store_parent;
SELECT n.tenant_id,n.application_id,r.id,n.id,r.id,'PAGE',r.display_name,r.sort_order,TRUE,'ACTIVE',UTC_TIMESTAMP(6),UTC_TIMESTAMP(6)
FROM iam_app_menu_node n JOIN iam_resource r ON r.id IN (UUID_TO_BIN('883f86a1-5bf5-49df-8284-4489c44e2682'),UUID_TO_BIN('fbb1be31-d42e-44fa-a887-14d5b5aa7df2'),UUID_TO_BIN('098c9bc3-3116-442a-9d2b-80093b72c21a'),UUID_TO_BIN('f1980cc2-a38e-40d5-9849-43046c7f9b94'),UUID_TO_BIN('9221b49e-3edb-428b-95d5-a76befc576fa'),UUID_TO_BIN('d387e5fe-c69f-42d7-bac1-d4c7eacd28ad')) WHERE n.resource_id=@store_parent AND n.deleted_at IS NULL;
SELECT n.tenant_id,n.application_id,r.id,n.id,r.id,'BUTTON',r.display_name,r.sort_order,FALSE,'ACTIVE',UTC_TIMESTAMP(6),UTC_TIMESTAMP(6)
FROM iam_app_menu_node n JOIN iam_resource r ON r.parent_id=n.resource_id AND r.id IN (UUID_TO_BIN('883f86a1-5bf5-49df-8284-4489c44e2682'),UUID_TO_BIN('fbb1be31-d42e-44fa-a887-14d5b5aa7df2'),UUID_TO_BIN('098c9bc3-3116-442a-9d2b-80093b72c21a'),UUID_TO_BIN('f1980cc2-a38e-40d5-9849-43046c7f9b94'),UUID_TO_BIN('9221b49e-3edb-428b-95d5-a76befc576fa'),UUID_TO_BIN('d387e5fe-c69f-42d7-bac1-d4c7eacd28ad'),UUID_TO_BIN('0675bda8-9131-4082-9897-5b07df73c515'),UUID_TO_BIN('719d1406-dc05-4ebc-8507-5122d86012eb'),UUID_TO_BIN('8c91f62e-d66f-492e-a0de-ea410846bb4d'),UUID_TO_BIN('51cb06d2-7d72-4e4d-8690-5d4a60ceb084'),UUID_TO_BIN('e91aefda-fb71-461e-961b-70b190ed7eac'),UUID_TO_BIN('9fa209d0-a893-4998-831a-617bc0e41cfb')) WHERE n.resource_id IN (UUID_TO_BIN('883f86a1-5bf5-49df-8284-4489c44e2682'),UUID_TO_BIN('fbb1be31-d42e-44fa-a887-14d5b5aa7df2'),UUID_TO_BIN('098c9bc3-3116-442a-9d2b-80093b72c21a'),UUID_TO_BIN('f1980cc2-a38e-40d5-9849-43046c7f9b94'),UUID_TO_BIN('9221b49e-3edb-428b-95d5-a76befc576fa'),UUID_TO_BIN('d387e5fe-c69f-42d7-bac1-d4c7eacd28ad')) AND n.deleted_at IS NULL;
UPDATE iam_app_settings SET version=version+1,updated_at=UTC_TIMESTAMP(6) WHERE application_id=@store_app;
UPDATE iam_tenant t SET policy_version=policy_version+1,version=version+1,updated_at=UTC_TIMESTAMP(6)
WHERE EXISTS(SELECT 1 FROM iam_app_menu_node n WHERE n.tenant_id=t.id AND n.resource_id IN (UUID_TO_BIN('883f86a1-5bf5-49df-8284-4489c44e2682'),UUID_TO_BIN('fbb1be31-d42e-44fa-a887-14d5b5aa7df2'),UUID_TO_BIN('098c9bc3-3116-442a-9d2b-80093b72c21a'),UUID_TO_BIN('f1980cc2-a38e-40d5-9849-43046c7f9b94'),UUID_TO_BIN('9221b49e-3edb-428b-95d5-a76befc576fa'),UUID_TO_BIN('d387e5fe-c69f-42d7-bac1-d4c7eacd28ad')) AND n.deleted_at IS NULL);
